    )
  ) AS REAL) * 100 / NULLIF(
    SUM(
      CASE WHEN T1.segment = 'SME' AND T2.date LIKE '2012%' THEN T2.consumption ELSE 0 END
    ),
    0
  ),
  CAST(SUM(
    CASE WHEN T1.segment = 'LAM' AND T2.date LIKE '2013%' THEN T2.consumption ELSE 0 END
  ) - SUM(
    CASE WHEN T1.segment = 'LAM' AND T2.date LIKE '2012%' THEN T2.consumption ELSE 0 END
  ) AS REAL) * 100 / NULLIF(
    SUM(
      CASE WHEN T1.segment = 'LAM' AND T2.date LIKE '2012%' THEN T2.consumption ELSE 0 END
    ),
    0
  ),
  CAST(SUM(
    CASE WHEN T1.segment = 'KAM' AND T2.date LIKE '2013%' THEN T2.consumption ELSE 0 END
  ) - SUM(
    CASE WHEN T1.segment = 'KAM' AND T2.date LIKE '2012%' THEN T2.consumption ELSE 0 END
  ) AS REAL) * 100 / NULLIF(
    SUM(
      CASE WHEN T1.segment = 'KAM' AND T2.date LIKE '2012%' THEN T2.consumption ELSE 0 END
    ),
    0
  )
